// Mock listings so the gallery has enough cards to page through while the real catalog is
// still three fixtures. The site lists them itself (lib/api/client.ts adds them after the real
// projects whether or not the API is up). The API does not list them but prices them for the
// shopping agent from contract/samples.json, generated by scripts/export-samples.mjs (a vitest
// test fails when that file drifts from this one). Checkout always refuses them.
//
// Every mock is a full contract `Project` (steps + materials), not just a card, so its detail
// page and the AG Grid render instead of 404ing. Output is deterministic (no Math.random) so
// server and client renders match and the build is reproducible.
//
// Mock ids start with "mock-"; the gallery labels those cards SAMPLE so nobody mistakes them
// for real priced projects. Delete this file and loadMocks() in lib/api/client.ts to remove them.
import type { components } from "../api/schema";
import { MOCK_ID_PREFIX } from "./ids";

// Re-exported so existing imports keep working; new code should import from ./ids.
export { MOCK_ID_PREFIX, isMockProject } from "./ids";

type Project = components["schemas"]["Project"];
type MaterialLine = components["schemas"]["MaterialLine"];
type Difficulty = Project["difficulty"];

