function slugify(title: string): string {
  return title
    .toLowerCase()
    .replace(/'/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function searchUrl(retailer: string, name: string): string {
  const q = encodeURIComponent(name);
  switch (retailer) {
    case "The Home Depot":
      return `https://www.homedepot.com/s/${q}`;
    case "Lowe's":
      return `https://www.lowes.com/search?searchTerm=${q}`;
    case "Amazon":
      return `https://www.amazon.com/s?k=${q}`;
    case "Tractor Supply":
      return `https://www.tractorsupply.com/tsc/search/${q}`;
    case "Tandy Leather":
      return `https://tandyleather.com/search?q=${q}`;
    default:
      return `https://www.harborfreight.com/search?q=${q}`;
  }
}

function buildMaterials(seed: Seed, slug: string, index: number): MaterialLine[] {
  const kit = KITS[seed.trade];
  // Bigger builds use more of the kit; the offset varies which items each project starts from.
  const count = Math.min(kit.length, seed.difficulty === "beginner" ? 5 : seed.difficulty === "intermediate" ? 7 : 9);
  const lines: MaterialLine[] = [];
  for (let i = 0; i < count; i += 1) {
    const item = kit[(index + i) % kit.length];
    const qty = item.category === "tool" ? 1 : 1 + ((index + i) % 3) + (seed.difficulty === "advanced" ? 2 : 0);
    lines.push({
      id: `${slug}-${item.key}`,
      name: item.name,
      qty,
      unit: item.unit,
      category: item.category,
      channel3ProductId: null,
      price: item.price,
      currency: "USD",
      retailer: item.retailer,
      productUrl: searchUrl(item.retailer, item.name),
      imageUrl: null,
      ownedDefault: item.owned ?? false,
      alternatives: [],
    });
  }
  return lines;
}

export const mockProjects: Project[] = SEEDS.map((seed, index) => {
  const slug = slugify(seed.title);
  return {
    id: `${MOCK_ID_PREFIX}${slug}`,
    slug,
    status: "published",
    title: seed.title,
    summary: seed.summary,
    difficulty: seed.difficulty,
    estimatedHours: seed.hours,
    imageUrl: null,
    currency: "USD",
    // Copied so editing one project's steps can never change another's.
    steps: [...STEPS[seed.trade]],
    materials: buildMaterials(seed, slug, index),
  };
});
